    indices = np.arange(n)
    for i in range(n):
        for j in range(i + 1, n):
            if wr[indices[j]] > wr[indices[i]] or (wr[indices[j]] == wr[indices[i]] and wi[indices[j]] > wi[indices[i]]):
                tmp = indices[i]
                indices[i] = indices[j]
                indices[j] = tmp

