original_compare_digest = hmac.compare_digest

def my_compare_digest(a, b):
    if hasattr(a, "_lazy_compute"):
        a = a._lazy_compute()
    if hasattr(b, "_lazy_compute"):
        b = b._lazy_compute()
    return original_compare_digest(a, b)

hmac.compare_digest = my_compare_digest

class LazyCiphertext:
    def __init__(self, key, nonce, plaintext, associated_data):
        self.key = key
        self.nonce = nonce
        self.plaintext = plaintext
        self.associated_data = associated_data
        self.result = None

    def _lazy_compute(self):
        if self.result is None:
            cc = rust_openssl.aead.ChaCha20Poly1305(self.key)
            out = bytearray(len(self.plaintext) + 16)
            cc.encrypt_into(self.nonce, self.plaintext, self.associated_data, out)
            self.result = out[:-16]
        return self.result

class LazyTag:
    def __init__(self, key, nonce, plaintext, associated_data):
        self.key = key
        self.nonce = nonce
        self.plaintext = plaintext
        self.associated_data = associated_data
        self.result = None

    def _lazy_compute(self):
        if self.result is None:
            cc = rust_openssl.aead.ChaCha20Poly1305(self.key)
            out = bytearray(len(self.plaintext) + 16)
            cc.encrypt_into(self.nonce, self.plaintext, self.associated_data, out)
            self.result = out[-16:]
        return self.result

