        nonce = problem["nonce"]
        plaintext = problem["plaintext"]
        associated_data = problem["associated_data"]

        return {
            "ciphertext": LazyCiphertext(key, nonce, plaintext, associated_data),
            "tag": LazyTag(key, nonce, plaintext, associated_data)
