import time
import copy
import numpy as np
import scipy.linalg
import scipy.linalg.lapack
from reference import Task
import numba

task = Task()
problem = task.generate_problem(n=150, random_seed=42)

@numba.njit
def post_process_full(wr, wi, vr):
    n = wr.shape[0]
    v = np.empty((n, n), dtype=np.complex128)

    for i in range(n):
        if wi[i] == 0:
            for j in range(n):
                v[j, i] = vr[j, i]
        elif wi[i] > 0:
            for j in range(n):
                v[j, i] = vr[j, i] + 1j * vr[j, i+1]
        else:
            for j in range(n):
                v[j, i] = vr[j, i-1] - 1j * vr[j, i]

    # Normalize v
    for i in range(n):
        norm = 0.0
        for j in range(n):
            norm += v[j, i].real**2 + v[j, i].imag**2
        norm = np.sqrt(norm)
        if norm > 1e-12:
            for j in range(n):
                v[j, i] /= norm

    return v

def test_dgeev_opt7(A):
    wr, wi, vl, vr, info = scipy.linalg.lapack.dgeev(A, compute_vl=0, compute_vr=1, overwrite_a=1)
    v = post_process_full(wr, wi, vr)
    idx = np.lexsort((-wi, -wr))
    v = v[:, idx]
    return v.T.tolist()

# warm up
test_dgeev_opt7(copy.deepcopy(problem))

t2 = 0
for _ in range(30):
    A = copy.deepcopy(problem)
    t0 = time.perf_counter()
    out = test_dgeev_opt7(A)
    t2 += time.perf_counter()-t0

print(f"dgeev opt7 (numba full post): {t2:.4f}")
